package org.firstinspires.ftc.teamcode.hardware;import com.qualcomm.robotcore.hardware.Gamepad;import com.qualcomm.robotcore.hardware.HardwareMap;import org.firstinspires.ftc.robotcore.external.Telemetry;import org.firstinspires.ftc.teamcode.subsystems.DriveSubsystem;import org.firstinspires.ftc.teamcode.subsystems.IntakeSubsystem;public class Superstructure extends Constants {    DriveSubsystem driveSS;    IntakeSubsystem intakeSS;    Gamepad driveCon;    Gamepad opCon;    Telemetry telemetry;    enum DumperStates {        TUCKED,        RAISE,        TIP    }    DumperStates curState;    public Superstructure(Gamepad driveCon, Gamepad opCon, HardwareMap hardwareMap, Telemetry telemetry) {        this.driveSS = new DriveSubsystem(hardwareMap, telemetry);        this.intakeSS = new IntakeSubsystem(hardwareMap, telemetry);        this.driveCon = driveCon;        this.opCon = opCon;        curState = DumperStates.TUCKED;        this.telemetry = telemetry;    }    public void Periodic(){        Drive();        teleData();    }    void Drive(){        driveSS.FieldCentric(driveCon.left_stick_y, driveCon.left_stick_x, driveCon.right_stick_x, driveCon.right_trigger > triggerThresh);    }    void teleData(){    }}/* CONTROLS* Gamepad1*   joysticks -> drive*   left trigger -> slow* Gamepad2*   a -> toggle intake*   dpad left -> switch dump states*   right bumper -> high dump*   left bumper - > mid dump* */